"use strict";

const paragraphOne = (lesson) =>
  `${lesson.title} is useful when a page must communicate ${lesson.goal}. ${lesson.detail} Treat the markup as a contract between the author, the browser, and the person using the page: choose an element for its documented meaning, provide enough context for it to be understood on its own, and keep the visible presentation separate from that meaning. This makes the result easier to navigate, style, test, and maintain. It also gives browsers and assistive technologies more reliable information than a visually similar collection of generic containers.`;

const paragraphTwo = (lesson) =>
  `When applying ${lesson.subject}, start with the simplest semantic HTML that satisfies the requirement, then verify the actual rendered behavior in a browser and with keyboard or assistive-technology checks where appropriate. ${lesson.practice} Keep fallback content and meaningful text available when a feature depends on scripting, media, or a particular browser capability. Check nesting, labels, accessible names, and responsive behavior rather than judging success only by appearance. This disciplined approach prevents common interoperability problems and makes later changes safer for both authors and users.`;

const question = (type, prompt, choices, correctChoiceId, explanation) => ({
  type,
  prompt,
  choices: choices.map(([id, text]) => ({ id, text })),
  correctChoiceId,
  explanation,
});

const makeLesson = (lesson) => {
  const explanations = [paragraphOne(lesson), paragraphTwo(lesson)];
  return {
    slug: lesson.slug,
    title: lesson.title,
    minutes: lesson.minutes,
    introduction: lesson.introduction,
    objectives: [
      `Explain when and why to use ${lesson.subject} in a real HTML document.`,
      `Create and validate an example that demonstrates ${lesson.goal}.`,
    ],
    explanation: explanations,
    terminology: lesson.terminology,
    syntax: lesson.syntax,
    codeExample: {
      code: lesson.code,
      lines: lesson.code.split("\n"),
      output: lesson.output,
    },
    commonMistakes: [
      `Using ${lesson.subject} decoratively without providing the meaning, fallback, or context that makes it useful to people and browsers.`,
      `Assuming that ${lesson.subject} will work correctly without checking its content, attributes, keyboard behavior, and behavior at different viewport sizes.`,
    ],
    bestPractices: [
      `Use ${lesson.subject} for its intended purpose, keep its content concise and accurate, and pair it with the surrounding context needed to understand it.`,
      `Validate the finished ${lesson.subject} with browser inspection and appropriate accessibility checks; preserve understandable fallback content wherever support or scripting may vary.`,
    ],
    exercise: {
      title: `Practice: ${lesson.title}`,
      difficulty: "intermediate",
      instructions: `Build a small, meaningful example of ${lesson.subject} that demonstrates ${lesson.goal}. Use semantic HTML, include the required content, and inspect how the browser presents it.`,
      starterCode: lesson.starter,
      requirements: lesson.requirements,
      hints: [
        `Start from the element and attributes shown in the ${lesson.title} example; confirm that each attribute has the correct value and purpose.`,
        `Compare your finished markup with the expected output and check that its text remains useful if styling or scripting is unavailable.`,
      ],
      solutionCode: lesson.solution,
      solutionExplanation: `The solution demonstrates ${lesson.goal} by using ${lesson.subject} in its intended context. Its content is deliberately explicit so that a reader can understand the information without relying on appearance alone. Review the element nesting and any relevant attributes, then test the result in a browser; where the feature has limitations, provide the fallback or surrounding text shown in the example.`,
    },
    quiz: [
      question(
        "multiple-choice",
        `Which approach best demonstrates ${lesson.subject}?`,
        [
          ["a", lesson.quizAnswer],
          ["b", lesson.quizWrongOne],
          ["c", lesson.quizWrongTwo],
        ],
        "a",
        `${lesson.quizExplanation} The correct answer follows the element's purpose rather than relying on a visual imitation or an undocumented browser assumption.`,
      ),
      question(
        "true-false",
        lesson.trueFalsePrompt,
        [["true", "True"], ["false", "False"]],
        lesson.trueFalseAnswer ? "true" : "false",
        lesson.trueFalseExplanation,
      ),
      question(
        "code-output",
        `In the following ${lesson.title} example, which result should a reader expect?`,
        [
          ["a", lesson.output],
          ["b", lesson.outputWrongOne],
          ["c", lesson.outputWrongTwo],
        ],
        "a",
        `Read the markup's actual content and semantics: ${lesson.outputReason}`,
      ),
    ],
    summary: `${lesson.title} applies ${lesson.subject} to ${lesson.goal}. Use the element deliberately, verify its browser behavior, and retain clear text and fallbacks for people and devices that cannot use every presentation feature.`,
  };
};

