const makeProjectLesson = (project) => {
  const lesson = makeLesson({
    ...project,
    subject: project.subject,
    goal: project.goal,
    detail: project.detail,
    practice: project.practice,
    introduction: project.introduction,
    minutes: project.minutes,
    terminology: project.terminology,
    syntax: project.syntax,
    code: project.solutionCode,
    output: project.expectedOutput,
    starter: project.starterCode,
    solution: project.solutionCode,
    requirements: project.validationRequirements,
    quizAnswer: project.quizAnswer,
    quizWrongOne: project.quizWrongOne,
    quizWrongTwo: project.quizWrongTwo,
    quizExplanation: project.quizExplanation,
    trueFalsePrompt: project.trueFalsePrompt,
    trueFalseAnswer: project.trueFalseAnswer,
    trueFalseExplanation: project.trueFalseExplanation,
    outputWrongOne: project.outputWrongOne,
    outputWrongTwo: project.outputWrongTwo,
    outputReason: project.outputReason,
  });
  lesson.exercise.title = `Project: ${project.title}`;
  lesson.exercise.difficulty = project.difficulty;
  lesson.exercise.instructions = project.projectDescription;
  lesson.exercise.starterCode = project.starterCode;
  lesson.exercise.requirements = project.validationRequirements;
  lesson.exercise.hints = project.hints;
  lesson.exercise.solutionCode = project.solutionCode;
  lesson.exercise.solutionExplanation = project.solutionExplanation;
  lesson.exercise.project = {
    description: project.projectDescription,
    learningObjectives: project.projectObjectives,
    requirements: project.projectRequirements,
    steps: project.steps,
    expectedOutput: project.expectedOutput,
    solutionCode: project.solutionCode,
    solutionExplanation: project.solutionExplanation,
    evaluationChecklist: project.evaluationChecklist,
  };
  lesson.summary = `${project.title} brings together ${project.goal}. Review the checklist, test the document in a browser, and confirm the semantic structure and interactions remain understandable without visual styling.`;
  return lesson;
};

